import{_ as a,o as l,c as r,a6 as t}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"关于本课程","description":"","frontmatter":{},"headers":[],"relativePath":"pebrel-course/about.md","filePath":"pebrel-course/docs/about.md"}'),i={name:"pebrel-course/about.md"};function o(h,e,n,s,d,c){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="关于本课程" tabindex="-1">关于本课程 <a class="header-anchor" href="#关于本课程" aria-label="Permalink to &quot;关于本课程&quot;">​</a></h1><p>本课程是一场锁定版本的源码走读：对象是 <a href="https://github.com/Kuddev/pebrel" target="_blank" rel="noreferrer">Pebrel</a>（原名 Nebula）——一个 Rust + GPUI 的 GPU 加速终端模拟器，兼作 SSH/SFTP 工作区与 AI CLI（Claude Code / Codex 等）会话宿主。全书 16 章覆盖其九 crate workspace 的 15 个可教学特性，每章配一个可在锁定 clone 上复跑的只读静态探针。</p><p><strong>主线问题</strong>：一个 GPU 加速终端如何同时成为 SSH 工作区与 AI CLI 会话的家？全书就是它的答案。</p><ul><li>输入：仓库 <a href="https://github.com/Kuddev/pebrel" target="_blank" rel="noreferrer">Kuddev/pebrel</a>，锁定 commit <code>360613aa6eedfa4e441d658d98db502e8a81442b</code></li><li>章节数：16 章全部完成（15 个教学特性 + 1 个全书对账复盘）</li><li>验证物：<code>companion/scripts/</code> 下 15 个探针共 398 条断言，<code>pnpm probes</code> 一键全绿</li></ul><h2 id="引用与许可" tabindex="-1">引用与许可 <a class="header-anchor" href="#引用与许可" aria-label="Permalink to &quot;引用与许可&quot;">​</a></h2><p>本课程逐字引用 Pebrel 的源码片段（含 TOML 规则与文档注释）。被引用片段依 <a href="https://www.gnu.org/licenses/gpl-3.0.txt" target="_blank" rel="noreferrer">GPL-3.0</a> 授权使用：出处标注为 <code>Kuddev/pebrel@360613aa6eedfa4e441d658d98db502e8a81442b:路径</code>，与锁定 commit 逐字一致（CRLF 行尾按内容归一）。Pebrel 及其贡献者保留全部版权；本课程的讲解文字独立成文，引用块内代码的许可以 GPL-3.0 为准。</p><h2 id="内容时效" tabindex="-1">内容时效 <a class="header-anchor" href="#内容时效" aria-label="Permalink to &quot;内容时效&quot;">​</a></h2><p>本课程全部事实锚定上述锁定 commit（主分支后续演进不自动生效）。第 10 章引用的屏幕证据 TOML 规则注释含日期化演化记录（如 2026-08-22 的恒假条件修正），正文已按时点标注；该章引用的注释内行号（如 <code>ai_agents.rs:528</code>）属改名前的历史锚点，实际语义位置以正文说明为准。</p><h2 id="能力阶梯" tabindex="-1">能力阶梯 <a class="header-anchor" href="#能力阶梯" aria-label="Permalink to &quot;能力阶梯&quot;">​</a></h2><ul><li>学完<a href="./01-repo-map.html">第 1 章</a>，你能用所有权地图判断任意改动的落点 crate 与禁区</li><li>学完<a href="./02-vt-grid.html">第 2 章</a>，你能追踪一条 CSI/OSC 序列从字节流到单元格状态变化的完整路径</li><li>学完<a href="./03-pty-event-loop.html">第 3 章</a>，你能讲清本地 shell 输出跨线程进入 UI 的每一步与平台分叉点</li><li>学完<a href="./04-split-tree.html">第 4 章</a>，你能把交互式布局规则读成可独立测试的纯函数</li><li>学完<a href="./05-gpui-shell.html">第 5 章</a>，你能解释多 pane 工作区的组装、resize 合同与资源清理合同</li><li>学完<a href="./06-ssh-session.html">第 6 章</a>，你能解释同一个 Term/渲染栈为何既吃 ConPTY 又吃 SSH channel</li><li>学完<a href="./07-sftp-engine.html">第 7 章</a>，你能算出给定 RTT 与分块下的单句柄吞吐上限</li><li>学完<a href="./08-ai-hook-bridge.html">第 8 章</a>，你能设计不打扰宿主 CLI 语义的跨进程事件桥</li><li>学完<a href="./09-ai-lifecycle.html">第 9 章</a>，你能对乱序事件样例推出 GateVerdict 的裁决</li><li>学完<a href="./10-screen-evidence.html">第 10 章</a>，你能为未适配 CLI 编写含负向证据的状态推断规则</li><li>学完<a href="./11-session-persistence.html">第 11 章</a>，你能设计崩溃安全的版本化快照与恢复护栏</li><li>学完<a href="./12-lua-config.html">第 12 章</a>，你能说明「执行本地受信代码」的配置边界与离线校验原理</li><li>学完<a href="./13-native-math.html">第 13 章</a>，你能读出排版编译管线的分层与共享常量合同</li><li>学完<a href="./14-answer-reader.html">第 14 章</a>，你能识别「复用入口」与「复制实现」两种结构</li><li>学完<a href="./15-completion-engine.html">第 15 章</a>，你能为假想补全源指出需要实现的 trait 方法</li><li>学完<a href="./16-review.html">第 16 章</a>，你能对任一假想改动走通「落点 → 禁区 → 影响面」三问</li></ul>',10)])])}const f=a(i,[["render",o]]);export{m as __pageData,f as default};
